package ge.opensoft.openservice;
import static ge.opensoft.openservice.Values.*;
import static ge.opensoft.openservice.WorkflowSupport.*;
import static ge.opensoft.openservice.CatalogueQuestionsAcceptance.*;
import static org.junit.jupiter.api.Assertions.*;
import java.util.*;
import java.util.concurrent.*;
final class CatalogueConditionsAcceptance {
 static Map<String,Object> when(Map<String,Object> question,String key,String value){question.put("when",map("key",key,"value",value));return question;}
 static List<Map<String,Object>> questions(){return List.of(question("kind","choice",true,List.of("Standard","Special")),when(question("needed","boolean",true,List.of()),"kind","Special"),when(question("reason","string",true,List.of()),"needed","true"),when(question("amount","integer",false,List.of()),"kind","Special"),when(question("start","date",false,List.of()),"needed","true"),question("comment","string",false,List.of()));}
 static String seed(WorkflowSupport h)throws Exception {h.account("ConditionalBuyer","requester");String id=result(h.json("POST",CATALOG,CatalogueAcceptance.offering("Conditional service",0,true),auth("admin")),201).get("offering_id").toString();result(h.json("PUT",CATALOG+"/"+id+"/questions",schema(1,questions()),auth("admin")),200);return id;}
 static Map<String,Object> order(Map<String,Object> answers){return map("revision",2,"details","Reviewed conditional request","key",id(),"answers",answers);}
 static String place(WorkflowSupport h,String id,Map<String,Object> body)throws Exception {return result(h.json("POST",CATALOG+"/"+id+"/order",body,auth("ConditionalBuyer")),201).get("sys_id").toString();}
 static void run(WorkflowSupport h)throws Exception {
  String id=seed(h);var standard=order(map("kind","Standard","reason","","needed","","amount","","start",""));String request=place(h,id,standard);assertEquals(List.of("kind","comment"),answers(h,request,"ConditionalBuyer").stream().map(a->a.get("key")).toList());assertEquals(request,place(h,id,standard));assertFalse(result(h.get("/api/now/table/sc_request/"+request,auth("ConditionalBuyer")),200).get("description").toString().contains("Question reason"));var values=map("kind","Special","needed","true","reason","Approved purpose <script>","amount","4","start","2026-11-18","comment","Retained");String special=place(h,id,order(values));assertEquals(6,answers(h,special,"ConditionalBuyer").size());String noNeed=place(h,id,order(map("kind","Special","needed","false")));assertEquals(List.of("kind","needed","amount","comment"),answers(h,noNeed,"ConditionalBuyer").stream().map(a->a.get("key")).toList());new Store(h.environment);assertEquals("Approved purpose <script>",answers(h,special,"ConditionalBuyer").get(2).get("value"));
  var changed=questions();changed.get(2).put("label","Changed label");result(h.json("PUT",CATALOG+"/"+id+"/questions",schema(2,changed),auth("admin")),200);assertEquals("Question reason",answers(h,special,"ConditionalBuyer").get(2).get("label"));assertEquals(request,place(h,id,standard));assertEquals(409,h.json("POST",CATALOG+"/"+id+"/order",order(values),auth("ConditionalBuyer")).statusCode());
 }
 static void answersAndAuthority(WorkflowSupport h)throws Exception {
  String id=seed(h),url=CATALOG+"/"+id+"/order";for(var answers:List.of(map("kind","Standard","reason","Hidden"),map("kind","Standard","needed","true","reason","Chained injection"),map("kind","Special"),map("kind","Special","needed","true"),map("kind","Special","needed","yes"),map("kind","Special","needed","false","amount","1.5"),map("kind","Special","needed","true","reason","Present","start","2026-02-30"),map("kind","Standard","unknown",""))){assertEquals(400,h.json("POST",url,order(answers),auth("ConditionalBuyer")).statusCode(),answers.toString());}assertEquals(0,CatalogueAssistAcceptance.count(h.store));h.account("ConditionalReader","reader");assertEquals(403,h.json("POST",url,order(map("kind","Standard")),auth("ConditionalReader")).statusCode());assertEquals(403,h.json("PUT",CATALOG+"/"+id+"/questions",schema(2,List.of()),auth("ConditionalBuyer")).statusCode());assertEquals(401,h.json("POST",url,order(map("kind","Standard")),null).statusCode());String group=h.add("sys_user_group").get("sys_id").toString();result(h.json("PUT",CATALOG+"/"+id+"/eligibility",map("group_id",group,"revision",2),auth("admin")),200);var body=order(map("kind","Standard"));body.put("revision",3);assertEquals(404,h.json("POST",url,body,auth("ConditionalBuyer")).statusCode());FulfilmentAcceptance.member(h,group,"ConditionalBuyer",true);assertNotNull(place(h,id,body));
 }
 static void definitions(WorkflowSupport h)throws Exception {
  try(var provider=new RecordQuestionsAcceptance.Provider(h.store,h.environment)){var action=ConnectorActionsAcceptance.spec(provider.alias,0,"POST");action.put("inputs",questions());assertEquals(400,h.json("POST",ConnectorActionsAcceptance.API,action,auth("admin")).statusCode(),"Catalogue-only conditions must not enter connector forms without conditional controls");assertEquals(0,provider.calls.get());}
  String id=seed(h),url=CATALOG+"/"+id+"/questions";var first=question("kind","choice",true,List.of("Standard","Special"));var bool=question("needed","boolean",false,List.of());var text=question("text","string",false,List.of());for(Object condition:List.of("invalid",map(),map("key","kind","value","Special","extra",true),map("key","missing","value","Special"),map("key","reason","value","Special"),map("key","kind","value","missing"),map("key","needed","value","yes"),map("key","text","value","match"),map("key",1,"value","Special"),map("key","kind","value",1))){var dependent=question("reason","string",true,List.of());dependent.put("when",condition);assertEquals(400,h.json("PUT",url,schema(2,List.of(first,bool,text,dependent)),auth("admin")).statusCode(),condition.toString());}assertEquals(400,h.json("PUT",url,schema(2,List.of(when(question("reason","string",true,List.of()),"kind","Special"),first)),auth("admin")).statusCode());var unknown=question("extra","string",false,List.of());unknown.put("script","evil");assertEquals(400,h.json("PUT",url,schema(2,List.of(unknown)),auth("admin")).statusCode());assertEquals(2,result(h.get(CATALOG+"/"+id,auth("admin")),200).get("revision"));
  var falseCondition=List.of(bool,when(question("reason","string",true,List.of()),"needed","false"));result(h.json("PUT",url,schema(2,falseCondition),auth("admin")),200);var required=order(map("needed","false"));required.put("revision",3);assertEquals(400,h.json("POST",CATALOG+"/"+id+"/order",required,auth("ConditionalBuyer")).statusCode());required.put("answers",map("needed","false","reason","Explicit no justification"));assertNotNull(place(h,id,required));
 }
 static void editor(WorkflowSupport h)throws Exception {
  String id=seed(h),url="/admin/catalogue/"+id+"/questions";var form=map("operation","save","revision",2,"key","reason","label","Question reason","type","string","required","true","choices","","condition_key","needed","condition_value","true");assertEquals(403,h.form(url,form,auth("admin")).statusCode());assertEquals(302,h.protectedForm(url,form,auth("admin")).statusCode());assertEquals(409,h.protectedForm(url,form,auth("admin")).statusCode());assertEquals(400,h.protectedForm(url,map("operation","remove","revision",3,"key","needed"),auth("admin")).statusCode());var source=map("operation","save","revision",3,"key","kind","label","Question kind","type","choice","required","true","choices","Standard","condition_key","","condition_value","");assertEquals(400,h.protectedForm(url,source,auth("admin")).statusCode());form.put("revision",3);form.put("condition_key","");assertEquals(400,h.protectedForm(url,form,auth("admin")).statusCode());form.put("condition_value","");assertEquals(302,h.protectedForm(url,form,auth("admin")).statusCode());var missing=new LinkedHashMap<>(form);missing.remove("condition_value");assertEquals(400,h.protectedForm(url,missing,auth("admin")).statusCode());missing=new LinkedHashMap<>(form);missing.remove("condition_key");assertEquals(400,h.protectedForm(url,missing,auth("admin")).statusCode());try(var db=h.store.open()){PlatformFoundationTest.bind(db);for(var bad:List.of(map("condition_key",1,"condition_value","true"),map("condition_key","needed","condition_value",1))){var input=new LinkedHashMap<>(form);input.put("revision",4);input.putAll(bad);assertEquals(400,assertThrows(Failure.class,()->CatalogueQuestions.edit(db,db.viewerId,id,input)).status);}db.connection.rollback();}
 }
 static void assistedAndConcurrent(WorkflowSupport h)throws Exception {
  String id=seed(h);try(var provider=new RecordQuestionsAcceptance.Provider(h.store,h.environment)){provider.settings.put("AI_CATALOGUE_ENABLED","true");var order=order(map("kind","Standard"));String token=CatalogueAssistAcceptance.result(h,id,CatalogueAssistAcceptance.review(order),"ConditionalBuyer").get("action_token").toString();var tampered=new LinkedHashMap<>(order);tampered.put("answers",map("kind","Standard","reason","Invisible"));assertEquals(400,h.json("POST",CatalogueAssistAcceptance.api(id),CatalogueAssistAcceptance.submit(tampered,token),auth("ConditionalBuyer")).statusCode());var result=CatalogueQuestionsAcceptance.result(h.json("POST",CatalogueAssistAcceptance.api(id),CatalogueAssistAcceptance.submit(order,token),auth("ConditionalBuyer")),201);assertEquals(2,answers(h,result.get("sys_id").toString(),"ConditionalBuyer").size());assertEquals(0,provider.calls.get());}
  var order=order(map("kind","Special","needed","true","reason","Concurrent request"));try(var pool=Executors.newFixedThreadPool(2)){var a=pool.submit(()->place(h,id,order));var b=pool.submit(()->place(h,id,order));assertEquals(a.get(),b.get());}assertEquals(2,CatalogueAssistAcceptance.count(h.store));
 }
}
